#!/usr/bin/env bash
# Phase 12 end-to-end on the local kind cluster, with the controller in ENFORCE mode using its real ServiceAccount:
# incident -> proposal -> (denied: unauthenticated / allow-list) -> operator approval -> REAL scale of order-service ->
# audit + events -> recovery measured -> kill switch. Telemetry is SYNTHETIC; the Kubernetes change is real.
# Prereqs: scripts/k8s-up.sh has been run.  Usage: scripts/k8s-remediation-e2e.sh
set -uo pipefail
cd "$(dirname "$0")/.."
NS=cloudpulse; K="kubectl -n $NS"
fail=0
check() { if eval "$2"; then echo "[PASS] $1"; else echo "[FAIL] $1"; fail=1; fi; }
py() { python3 -c "import sys,json;d=json.load(sys.stdin);r=($1);print(json.dumps(r) if isinstance(r,(dict,list)) else r)"; }
$K port-forward svc/remediation-controller 18086:8086 >/dev/null 2>&1 & PF1=$!
$K port-forward svc/operations-service 18083:8083 >/dev/null 2>&1 & PF2=$!
$K port-forward svc/identity-service 18087:8087 >/dev/null 2>&1 & PF3=$!
trap 'kill $PF1 $PF2 $PF3 2>/dev/null' EXIT
sleep 3
# Real identities from identity-service (credentials were generated by k8s-up.sh into .run/identity-credentials.txt)
idjwt() { for _ in $(seq 1 24); do t=$(curl -s -D - -o /dev/null -X POST localhost:18087/auth/login -H 'Content-Type: application/json' -d "{\"username\":\"$1\",\"password\":\"$(awk -v u=$1 '$1==u{print $2}' .run/identity-credentials.txt)\"}" | awk -F'[=;]' 'tolower($1)=="set-cookie: cp_session"{print $2}'); [ -n "$t" ] && { echo "$t"; return; }; sleep 5; done; }
OP_JWT=$(idjwt operator); ADMIN_JWT=$(idjwt admin); VIEWER_JWT=$(idjwt viewer)
TOKEN=$OP_JWT
RC=http://localhost:18086; OPS=http://localhost:18083
rem() { curl -s "$RC/api/v1/remediations?limit=50"; }
wait_for() { for _ in $(seq 1 "${3:-40}"); do eval "$2" && return 0; sleep 2; done; return 1; }

# The cooldown guard is real, so a re-run right after a previous run would (correctly) be BLOCKED. Wait it out.
WAIT=$(curl -s "$RC/api/v1/remediations?limit=50" | python3 -c "
import sys,json,datetime as dt
d=json.load(sys.stdin); cd=int(json.loads(sys.argv[1])['cooldownMinutes'])
ex=[dt.datetime.fromisoformat(v['remediation']['executedAt'].replace('Z','+00:00')) for v in d if v['remediation']['service']=='order-service' and v['remediation']['executedAt']]
if not ex: print(0)
else:
    left=(max(ex)+dt.timedelta(minutes=cd,seconds=15)-dt.datetime.now(dt.timezone.utc)).total_seconds(); print(max(0,int(left)))" "$(curl -s $RC/api/v1/remediation/status)")
[ "$WAIT" -gt 0 ] && { echo "   cooldown from a previous run still active: waiting ${WAIT}s (this is the guard working)"; sleep "$WAIT"; }

# The hourly rate limit is real too. If earlier runs used it up, raise it for the duration of this test only (restored at the end).
EXEC_LAST_HOUR=$(curl -s "$RC/api/v1/remediations?limit=200" | python3 -c "
import sys,json,datetime as dt
d=json.load(sys.stdin);now=dt.datetime.now(dt.timezone.utc)
print(sum(1 for v in d if v['remediation']['executedAt'] and (now-dt.datetime.fromisoformat(v['remediation']['executedAt'].replace('Z','+00:00'))).total_seconds()<3600))")
RAISED=0
if [ "$EXEC_LAST_HOUR" -ge 3 ]; then
  echo "   $EXEC_LAST_HOUR actions in the last hour: temporarily raising REMEDIATION_MAX_ACTIONS_PER_HOUR for this test run"
  $K set env deploy/remediation-controller REMEDIATION_MAX_ACTIONS_PER_HOUR=20 >/dev/null && $K rollout status deploy/remediation-controller --timeout=180s >/dev/null && RAISED=1
  kill $PF1 2>/dev/null; $K port-forward svc/remediation-controller 18086:8086 >/dev/null 2>&1 & PF1=$!; sleep 4
fi

echo "--- 0. controller posture"
check "mode=enforce, approvals enabled, kill switch off" "curl -s $RC/api/v1/remediation/status | py 'd[\"mode\"]==\"enforce\" and d[\"approvalsEnabled\"] and not d[\"killSwitch\"]' | grep -q True"
check "allow-list is exactly order/inventory/operations; automated policy disabled" "curl -s $RC/api/v1/remediation/status | py 'sorted(d[\"allowList\"])==[\"inventory-service\",\"operations-service\",\"order-service\"] and not d[\"automatedPolicy\"][\"autoApprove\"]' | grep -q True"
check "controller SA cannot touch analytics-sink or scale deployments at the Kubernetes level (RBAC backstop)" "[ \"\$(kubectl auth can-i patch horizontalpodautoscalers/analytics-sink -n $NS --as=system:serviceaccount:$NS:remediation-controller)\" = no ] && [ \"\$(kubectl auth can-i patch deployments/order-service --subresource=scale -n $NS --as=system:serviceaccount:$NS:remediation-controller)\" = no ]"
BASE_REPLICAS=$($K get deploy order-service -o jsonpath='{.spec.replicas}'); BASE_FLOOR=$($K get hpa order-service -o jsonpath='{.spec.minReplicas}'); SINK_REPLICAS=$($K get deploy analytics-sink -o jsonpath='{.spec.replicas}')

# Start from a clean slate: an incident left open by an interrupted earlier run would never produce a new proposal (one per incident).
if curl -s "$OPS/api/v1/incidents?status=OPEN" | py 'any(i["service"] in ("order-service","analytics-sink") for i in d)' | grep -q True; then
  echo "   open incident left from an earlier run: feeding normal synthetic telemetry until it resolves"
  ./scripts/simulate-telemetry.py --api $OPS --services order-service,analytics-sink --scenario normal --duration 30 --interval 1 >/dev/null 2>&1
  for _ in $(seq 1 30); do curl -s -X POST $OPS/api/v1/detection/evaluate >/dev/null; curl -s "$OPS/api/v1/incidents?status=OPEN" | py 'not any(i["service"] in ("order-service","analytics-sink") for i in d)' | grep -q True && break; sleep 3; done
fi

echo "--- 1. create incidents (SYNTHETIC overload on order-service and on analytics-sink)"
./scripts/simulate-telemetry.py --api $OPS --services order-service,analytics-sink --scenario normal --backfill-minutes 15 --duration 0 >/dev/null 2>&1
./scripts/simulate-telemetry.py --api $OPS --services order-service,analytics-sink --scenario spike --duration 24 --interval 2 >/dev/null 2>&1
check "proposal appears for order-service (scale $BASE_REPLICAS -> $((BASE_REPLICAS+2)))" "wait_for x \"rem | py 'any(v[\\\"remediation\\\"][\\\"service\\\"]==\\\"order-service\\\" and v[\\\"remediation\\\"][\\\"status\\\"]==\\\"PROPOSED\\\" for v in d)' | grep -q True\" 45"
R=$(rem | py 'next(v["remediation"] for v in d if v["remediation"]["service"]=="order-service" and v["remediation"]["status"]=="PROPOSED")')
RID=$(echo "$R" | py 'd["id"]' 2>/dev/null || python3 -c "import json,sys;print(json.loads('''$R''')['id'])")
echo "   remediation id: $RID"
check "proposal is bounded, explained and has not touched the cluster yet" "[ \$($K get hpa order-service -o jsonpath='{.spec.minReplicas}') -eq $BASE_FLOOR ] && curl -s $RC/api/v1/remediations/$RID | py 'd[\"remediation\"][\"toReplicas\"]==d[\"remediation\"][\"fromReplicas\"]+2 and \"allow-list: ok\" in d[\"guardrails\"]' | grep -q True"
check "analytics-sink incident is BLOCKED by the allow-list, never scaled" "wait_for x \"rem | py 'any(v[\\\"remediation\\\"][\\\"service\\\"]==\\\"analytics-sink\\\" and v[\\\"remediation\\\"][\\\"status\\\"]==\\\"BLOCKED\\\" and \\\"DENIED\\\" in v[\\\"remediation\\\"][\\\"guardrailNotes\\\"] for v in d)' | grep -q True\" 20 && [ \$($K get deploy analytics-sink -o jsonpath='{.spec.replicas}') -eq $SINK_REPLICAS ]"

echo "--- 2. authorisation"
check "approve without a token -> 401" "[ \$(curl -s -o /dev/null -w '%{http_code}' -X POST $RC/api/v1/remediations/$RID/approve -H 'Content-Type: application/json' -d '{}') = 401 ]"
check "approve with a forged/invalid token -> 401" "[ \$(curl -s -o /dev/null -w '%{http_code}' -X POST $RC/api/v1/remediations/$RID/approve -H 'Authorization: Bearer nope' -H 'Content-Type: application/json' -d '{}') = 401 ]"
check "approve with a VIEWER identity -> 403" "[ \$(curl -s -o /dev/null -w '%{http_code}' -X POST $RC/api/v1/remediations/$RID/approve -H \"Authorization: Bearer $VIEWER_JWT\" -H 'Content-Type: application/json' -d '{}') = 403 ]"
check "still PROPOSED and unchanged after failed attempts" "curl -s $RC/api/v1/remediations/$RID | py 'd[\"remediation\"][\"status\"]==\"PROPOSED\"' | grep -q True && [ \$($K get hpa order-service -o jsonpath='{.spec.minReplicas}') -eq $BASE_FLOOR ]"
check "blocked (analytics-sink) remediation cannot be approved -> 409" "BID=\$(rem | py 'next(v[\"remediation\"][\"id\"] for v in d if v[\"remediation\"][\"service\"]==\"analytics-sink\")'); [ \$(curl -s -o /dev/null -w '%{http_code}' -X POST $RC/api/v1/remediations/\$BID/approve -H \"Authorization: Bearer $TOKEN\" -H 'Content-Type: application/json' -d '{}') = 409 ]"

echo "--- 3. approved action is executed for real"
check "authorised operator approves" "curl -s -X POST $RC/api/v1/remediations/$RID/approve -H \"Authorization: Bearer $TOKEN\" -H 'Content-Type: application/json' -d '{\"comment\":\"synthetic overload drill\"}' | py 'd[\"remediation\"][\"status\"]==\"APPROVED\" and d[\"remediation\"][\"decidedBy\"]==\"operator\"' | grep -q True"
check "controller raises the order-service HPA capacity floor to $((BASE_FLOOR+2)) via the Kubernetes API" "wait_for x \"[ \\\$($K get hpa order-service -o jsonpath='{.spec.minReplicas}') -eq $((BASE_FLOOR+2)) ]\" 20"
check "remediation is MONITORING with executedAt set" "wait_for x \"curl -s $RC/api/v1/remediations/$RID | py 'd[\\\"remediation\\\"][\\\"status\\\"]==\\\"MONITORING\\\" and bool(d[\\\"remediation\\\"][\\\"executedAt\\\"])' | grep -q True\" 10"
check "the HPA brings the deployment up to the floor and keeps it there (no fight with the autoscaler)" "wait_for x \"[ \\\$($K get deploy order-service -o jsonpath='{.status.readyReplicas}') -ge $((BASE_FLOOR+2)) ]\" 60 && sleep 45 && [ \$($K get deploy order-service -o jsonpath='{.status.readyReplicas}') -ge $((BASE_FLOOR+2)) ]"
check "second approval attempt is rejected (idempotent, no double execution) -> 409" "[ \$(curl -s -o /dev/null -w '%{http_code}' -X POST $RC/api/v1/remediations/$RID/approve -H \"Authorization: Bearer $TOKEN\" -H 'Content-Type: application/json' -d '{}') = 409 ]"

echo "--- 4. audit and events"
check "audit trail is complete and ordered (PROPOSED, APPROVAL_REQUIRED, APPROVED, EXECUTING, EXECUTED)" "curl -s $RC/api/v1/remediations/$RID/audit | py '[a[\"event\"] for a in d]' | python3 -c 'import sys,ast;e=ast.literal_eval(sys.stdin.read());want=[\"PROPOSED\",\"APPROVAL_REQUIRED\",\"APPROVED\",\"EXECUTING\",\"EXECUTED\"];i=[e.index(w) for w in want];sys.exit(0 if i==sorted(i) else 1)'"
check "audit records WHO approved" "curl -s $RC/api/v1/remediations/$RID/audit | py 'any(a[\"event\"]==\"APPROVED\" and a[\"actor\"]==\"operator\" for a in d)' | grep -q True"
PGPOD=postgres-0; PGPW=$($K get secret cloudpulse-db -o jsonpath='{.data.password}' | base64 -d)
pgq() { for _ in 1 2 3; do o=$($K exec $PGPOD -- env PGPASSWORD=$PGPW psql -U cloudpulse -d cloudpulse -c "$1" 2>&1); echo "$o" | grep -q "unable to upgrade\|error: Internal error" || break; sleep 2; done; echo "$o"; }   # retry transient exec failures
UPD=$(pgq "update remediation.remediation_audit set actor='x'"); DEL=$(pgq "delete from remediation.remediation_audit")
check "audit log is append-only at the database level (UPDATE and DELETE are refused)" "echo \"\$UPD\" | grep -q 'append-only' && echo \"\$DEL\" | grep -q 'append-only'"
EV=$($K exec deploy/pubsub-emulator -- curl -s -X POST -H 'Content-Type: application/json' localhost:8085/v1/projects/cloudpulse-ai-poc/subscriptions/remediation-events-ops-sub:pull -d '{"maxMessages":100,"returnImmediately":true}')
check "remediation.event messages reached the remediation-events topic (PROPOSED, APPROVED, MONITORING)" "echo '$EV' | python3 -c 'import sys,json,base64;ms=json.load(sys.stdin).get(\"receivedMessages\",[]);st={json.loads(base64.b64decode(m[\"message\"][\"data\"]))[\"data\"][\"status\"] for m in ms};sys.exit(0 if {\"PROPOSED\",\"APPROVED\",\"MONITORING\"}<=st else 1)'"

echo "--- 5. recovery is measured"
./scripts/simulate-telemetry.py --api $OPS --services order-service,analytics-sink --scenario normal --duration 40 --interval 1 >/dev/null 2>&1
check "incident resolves and the controller records RECOVERED with a measured time" "wait_for x \"curl -s -X POST $OPS/api/v1/detection/evaluate >/dev/null; curl -s $RC/api/v1/remediations/$RID | py 'd[\\\"remediation\\\"][\\\"status\\\"]==\\\"RECOVERED\\\" and d[\\\"remediation\\\"][\\\"timeToRecoverSeconds\\\"] is not None' | grep -q True\" 45"
curl -s $RC/api/v1/remediations/$RID | py '"   outcome: " + d["remediation"]["outcomeDetail"]'
check "outcome is honest about synthetic telemetry" "curl -s $RC/api/v1/remediations/$RID | py '\"SYNTHETIC\" in d[\"remediation\"][\"outcomeDetail\"]' | grep -q True"

check "emergency capacity floor is restored after recovery (HPA min back to $BASE_FLOOR)" "wait_for x \"[ \\\$($K get hpa order-service -o jsonpath='{.spec.minReplicas}') -eq $BASE_FLOOR ]\" 10 && curl -s $RC/api/v1/remediations/$RID/audit | py 'any(a[\"event\"]==\"CAPACITY_FLOOR_RESTORED\" for a in d)' | grep -q True"

echo "--- 6. kill switch"
check "kill switch requires the token" "[ \$(curl -s -o /dev/null -w '%{http_code}' -X POST $RC/api/v1/remediation/kill-switch -H 'Content-Type: application/json' -d '{\"enabled\":true}') = 401 ]"
check "an OPERATOR cannot use the kill switch (403) but an ADMIN can pause and resume execution" "[ \$(curl -s -o /dev/null -w '%{http_code}' -X POST $RC/api/v1/remediation/kill-switch -H \"Authorization: Bearer $OP_JWT\" -H 'Content-Type: application/json' -d '{\"enabled\":true}') = 403 ] && curl -s -X POST $RC/api/v1/remediation/kill-switch -H \"Authorization: Bearer $ADMIN_JWT\" -H 'Content-Type: application/json' -d '{\"enabled\":true}' | py 'd[\"killSwitch\"]' | grep -q True && curl -s $RC/api/v1/remediation/status | py 'd[\"killSwitch\"]' | grep -q True && curl -s -X POST $RC/api/v1/remediation/kill-switch -H \"Authorization: Bearer $ADMIN_JWT\" -H 'Content-Type: application/json' -d '{\"enabled\":false}' | py 'not d[\"killSwitch\"]' | grep -q True"
check "kill switch use is audited" "curl -s '$RC/api/v1/remediation/audit?limit=20' | py 'any(a[\"event\"]==\"KILL_SWITCH_ON\" for a in d)' | grep -q True"

[ "$RAISED" = 1 ] && $K set env deploy/remediation-controller REMEDIATION_MAX_ACTIONS_PER_HOUR- >/dev/null
kill $PF1 $PF2 $PF3 2>/dev/null
echo; [ $fail -eq 0 ] && echo "PHASE 12 K8S E2E: ALL PASSED" || echo "PHASE 12 K8S E2E: FAILURES"
exit $fail
